WITH department_summary AS (SELECT dept_id, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(level))) AS level_values, MAX(hire_date) AS latest_hire_date FROM employees WHERE job_title <> 'Director' GROUP BY dept_id) SELECT d.id, d.location, ds.level_values, ds.latest_hire_date FROM departments d LEFT OUTER JOIN department_summary ds ON d.id = ds.dept_id ORDER BY latest_hire_date, ds.level_values;
